You are an expert mathematician. Your task is to provide a thorough and correct proof for a mathematical problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematician.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

From now on, we assume we have an $n$-point dataset $P\in\R^d$ under the Euclidean distance, where $d\gg \log n$. For a graph $H$, we use $\d_H(p,q)$ to denote the shortest path distance between $p$ to $q$ in $H$. We also let $\Delta$ be the aspect ratio of $P$: $\Delta=\tfrac{\max_{p,q\in P} \|p-q\|_2}{\min_{p,q\in P, p\neq q} \|p-q\|_2}$.

\section{Undirected Non-metric Steiner Spanners}\label{sec:undirected}

\begin{theorem}[See Section~\ref{sec:undirected}]\label{thm:ubUndir_intro}
    Fix $\eps\in(0,1)$. For any dataset $P\in \R^d$, we can construct an undirected graph $H$ on vertices $P\cup S$, such that for any $p,q\in P$, 
    $$
    \|p-q\|_2\le \d_H(p,q) < (1+\eps) \cdot \|p-q\|_2.
    $$
    Furthermore, the construction time, the number of edges of $H$ and the size of $S$ are bounded by $O(n^{2-\Omega(\eps^3)}\log \Delta)$, where $\Delta$ is the aspect ratio of $P$. 
\end{theorem}

\begin{lemma}[Data-independent LSH from Section~3 of \cite{alrw17}]\label{lem:lsh}
Let $r = (\log n)^{-1/8}$ be a fixed parameter, $c=1+\eps$ be the approximation ratio. There is a data structure that, takes a random seed $s$, implicitly \footnote{$T$ can be super-polynomially large.} gives two random collections of subspaces $A_1,A_2,\cdots,A_T\subset \R^d$ and $B_1,B_2,\cdots, B_T \subset \R^d$. For any point $p$, denote $\mathcal{A}_p = \{A_i : p \in A_i\}$ as the set of subspaces $A_i$ that contains $p$. Similarly, define $\mathcal{B}_p= \{B_i : p\in B_i\}$.
Then, for any $n=\omega(1)$, we have
\begin{enumerate}
\item $\forall p\in S^{d-1}$, $\E_s[|\mathcal{A}_p|] \leq n^{1/\eps^2 + O(1/\eps)}$;
\item $\forall p\in S^{d-1}$, $\E_s[|\mathcal{B}_p|] = n^{o(1)}$;
\item $\forall p,q\in S^{d-1}$ that $\|p-q\|_2 \leq r$, $\forall i\in [T]$,
\[
\Pr_s[p\in A_i \mid q\in B_i] \geq n^{-o(1)};
\]
\item $\forall p,q\in S^{d-1}$ that $\|p-q\|_2 \geq c\cdot r$, $\forall i\in [T]$,
\[
\Pr_s[p\in A_i \mid q\in B_i] \leq \frac{1}{n};
\]
\item $\forall p\in S^{d-1}$, one can find all $A_i \in \mathcal{A}_p$ in $O(|\mathcal{A}_p|\cdot n^{o(1)}$ time, and all $B_i \in \mathcal{B}_p$ in $O(|\mathcal{B}_p|\cdot n^{o(1)})$ time.
\end{enumerate}
\end{lemma}

\begin{lemma}[FNS data structure \cite{I-thesis, alrw17}]\label{lem:fns}
There is a $c$-approximate Furthest Neighbor Search data structure with $O(n^{1+\rho_P+o(1)})$ preprocessing time and $O(n^{\rho_Q+o(1)})$ query time, for any $\rho_Q, \rho_P>0$ satisfying the trade-off of:
\[
c^2\sqrt{\rho_Q} + (c^2-1)\sqrt{\rho_P} = \sqrt{2c^2-1}.
\]
\end{lemma}

\begin{algorithm}[h]\caption{}\label{alg:directed}
\begin{algorithmic}[1]
\Function{Build Spanner}{$P\subseteq S^{d-1}$, $r,\eps > 0$}
\State Let $n=|P|$ and $m = n^{\eps^2/4}$
\State Initialize the spanner $H=(P,\emptyset)$ as a graph with vertex set $P$ but no edges
\For{$\textrm{it} = 1,2,\cdots,n^{o(1)}$} \Comment{Repeat $n^{o(1)}$ rounds to boost success probability}
    \State Arbitrarily partition $P$ into $n/m$ groups $P_1,\cdots P_{n/m}$ each of size $m$
    \State Let $\{A_j,B_j\}_{j\in [T]}$ be the LSH function stated in Lemma~\ref{lem:lsh}
    \State \Comment{Plug in parameter $c_1\leftarrow 1+\eps$ and $n\leftarrow Km$ for some $K=|P|^{o(1)}$}
    \State Compute $Q_j \leftarrow P\cap B_j$, $\forall j\in [T]$
    \For{$i\in [n/m]$,~$j\in[T]$}
        \State Calculate $P_{i,j} \leftarrow P_i \cap A_j$
        \State $V_{i,j}\leftarrow \emptyset$
        \State Build FNS data structure for $P_{i,j}$ using Lemma~\ref{lem:fns}
        \State \Comment{Plug in parameter $c_2\leftarrow 1+\eps$, $\rho_P\leftarrow 2/\eps^2$ and $\rho_Q\leftarrow 0$.  \label{line:alg1_fns}}
        \For{$q\in Q_j$}
            \State Query $q$ into the FNS data structure for $P_{ij}$ to get  $f$, the $c_2$-approximate furthest point
            \If{$\|q-f\|_2 \leq c_1r$} \label{line:fns_test}
                \State Add $q$ to $V_{i,j}$
            \EndIf
        \EndFor
        \State Create a new Steiner node $s_{ij}$ in $H$ \label{line:create_star_start}
        \State For all $q\in V_{i,j}$, add a directed edge $(q,s_{ij})$ with length $0$ to $H$ \label{line:add_edge_1}
        \State For all $p\in P_{i,j}$, add a directed edge $(s_{ij},p)$ with length $(1+3\eps)r$ to $H$ \label{line:add_edge_2}
        \label{line:create_star_end}
    \EndFor
\EndFor
\State \Return $H$
\EndFunction
\end{algorithmic}
\end{algorithm}

\begin{observation}\label{obs:alg1}
Let $P_{i,j}$ and $Q_j$ be defined in Algorithm~\ref{alg:directed}. We have
\begin{enumerate}
\item for all $i,j$, $P_{i,j} \subseteq P_i$ and $|P_i|=m$.
\item $\sum_j |Q_j| = n^{1+o(1)}$;
\item $\sum_{i,j} \E[|P_{i,j}|] = n^{5/4+O(\eps)}$;
\item $\forall j, \sum_{i}|P_{i,j}| \leq n$, 
\item $i\in [n/m]$ and $m = n^{\eps^2/4}$.
\end{enumerate}
\end{observation}

\begin{definition}[Average square distance]\label{def:avg}
For a point set $A$, define $\avg(A) = \sqrt{\E_{p,q\in A}[\|p-q\|_2^2]}$.
Define $\avg_{\max}(A) = \max_{S\subseteq A}\avg(S)$.
\end{definition}

\begin{proposition}\label{pro:biclique}
If two sets of points $A,B$ satisfy $\max_{p\in A,q\in B}\|p-q\|_2\le r$, then $\avg_{\max}(A) + \avg_{\max}(B) \le 2r$.
\end{proposition}

\begin{definition}[Low diameter decomposition]\label{def:diameter_decomposition}
Let $A$ be a point set. We say $A_1,\cdots, A_T$ is an \emph{$r$-diameter decomposition} of $A$, if they form a partition of $A$, and every $A_i$ has diameter at most $r$.
\end{definition}

\begin{lemma}\label{lem:gadget}
Fix $r,\eps>0$. Suppose we have two point sets $A, B$ with $\max_{p\in A,q\in B}\|p-q\|_2\le r$. Let $x,y > 0$ be any real number such that $x + y \leq 2(1+\eps)r$. Given $A_1,\cdots, A_k$, an $x$-diameter decomposition of $A$, and $B_1,\cdots B_l$, a $y$-diameter decomposition of $B$, we can build an undirected graph $H$ such that for $\d_H$ the shortest path distance in $H$:
    \begin{itemize}
        \item for all $p \in A$, $q\in B$, $\d_H(p,q)\le (1+\eps)r$;
        \item for all $p,q\in A\cup B$, $\d_H(p,q)\ge \|p-q\|_2$,
    \end{itemize}
and the size of $H$ is $O(|A|\cdot l + k\cdot |B|)$. The construction time is $O(|H|)$.
\end{lemma}

Namely, if two points $p,q$ have distance $\leq r$, we say they are a \emph{$r$-close} pair. If their distance is $>r$, we say they are a \emph{$r$-far pair}.

\begin{algorithm}[h]\caption{}\label{alg:undirected}
\begin{algorithmic}[1]
\Function{Extract Clusters}{$P\subseteq S^{d-1}$, $a > 0$, $\eps > 0$, $c > 0$, $t>0$}
\State \Comment{Input guarantee: at least $|P|^{2-t}$ pairs of points are $a$-close.}
\State Let $n=|P|$.
\State Let $h$ be a random $(a, (1+\eps)a, p_1, p_2)$-LSH function, with $p_1 = n^{-c}$, $p_2 = n^{-(1+\eps)c}$. \label{line:pick_hash_function}
\State Partition $P$ into $1/p_2$ buckets using $h$. 
\State \Comment{See the proof of Lemma~\ref{lem:cluster_extraction} for the reason why there are $\le 1/p_2$ buckets.}
\State For each bucket $i$, let $C_{h,i}$ be the number of $a$-close pairs in this bucket. Similarly, let $F_{h,i}$ be the number of $(1+\eps)a$-far pairs.
\If{$\exists i$, such that $C_{h,i} \geq \frac{p_1p_2}{4}n^{2-t}$ and $F_{h,i}/C_{h/i} \leq 16\frac{p_2}{p_1}n^t$}\label{line:if}
\State Let $B_i$ be all points in bucket $i$.
\Repeat\label{line:repeat}
    \State randomly pick $k=n^{(\eps c -t)/2}/10$ points from $B_i$.
    \If{they are pairwise $a$-close pairs}
        \State form a cluster with them and delete them from $B_i$ \label{line:extract}
    \EndIf
    \Until{formed $C_{h,i}/(10nk)$ clusters.}
\Else \State Go back to Line~\ref{line:pick_hash_function}
\EndIf
\State \Return all formed clusters
\EndFunction
\end{algorithmic}
\end{algorithm}

\begin{lemma}[cluster extraction]\label{lem:cluster_extraction}
Fix an $n$-point set $P\subset \R^d$. Let $\eps \in (0,2)$ be the approximation parameter. Let $a > 0$ be a parameter such that there are at least $n^{2-t}$ $a$-close pairs, where $t=O(\eps)$.

For any parameter $c \in (0, 0.2]$ with $\eps c > t$, Algorithm~\ref{alg:undirected} outputs disjoint clusters each with size $\Omega(n^{(\eps c - t)/2})$. Each cluster has diameter $(1+\eps)a$, i.e., all its points are $(1+\eps)a$-close. Moreover, the total number of points in all clusters is $\Omega(n^{1-2c-\eps c -t})$. Algorithm~\ref{alg:undirected} can be implemented to run in $O(n^{1+c+t})$ expected time.
\end{lemma}

\begin{lemma}\label{lem:avg_dis_square}
Given a point set $A$ and $\eps \in (0,1/2)$, let the average distance be define in Def.~\ref{def:avg}, i.e., 
$\avg(A)=\sqrt{\E_{p,q\in A}[\|p-q\|_2^2]}$. Then, there are at least $|A|^2\eps$ pairs of $p,q\in A$ such that $\|p-q\|_2\leq (1+\eps)\avg(A)$.
\end{lemma}

In particular, we will use Algorithm~\ref{alg:undirected} to compute
$(\avg_{\max}(A) + \eps\cdot \dia(A))$-diameter decomposition of a set $A$, where $\dia(A)$ is the diameter of $A$. 

\begin{lemma}\label{lem:compute_dec}
Fix $\eps >0$. Consider a set $A$ of size $n > \omega(1/\eps)$. We can construct $A_1,\cdots,A_T$, which is a $(\avg_{\max}(A) + \eps\cdot \dia(A))$-diameter decomposition of $A$ in  $O(n^{1.4})$ time. Furthermore, we have $T\leq n^{1-\Omega(\eps)}$.
\end{lemma}


